from pathlib import Path

import yaml

SETTINGS_FILE = "model-settings.yml"


def load_model_settings() -> list[dict]:
    path = Path(__file__).with_name("resources") / SETTINGS_FILE
    return yaml.safe_load(path.read_text())


def settings_for(name: str) -> dict | None:
    return next((entry for entry in load_model_settings() if entry["name"] == name), None)

